function calculate() {
      const visitors = parseFloat(document.getElementById('inpVisitors').value) || 0;
      const pvRatio = parseFloat(document.getElementById('inpPvRatio').value) || 1.5;
      const ecpm = parseFloat(document.getElementById('inpCountry').value) || 4.0;
      const fx = parseFloat(document.getElementById('inpFxRate').value) || 1350;

      const dailyPv = visitors * pvRatio;
      const monthlyPv = dailyPv * 30;

      const dailyUsd = (dailyPv / 1000) * ecpm;
      const monthlyUsd = (monthlyPv / 1000) * ecpm;
      const flippaUsd = monthlyUsd * 30; // 보통 월수익의 28~35배 매각

      const dailyKrw = dailyUsd * fx;
      const monthlyKrw = monthlyUsd * fx;
      const flippaKrw = flippaUsd * fx;

      document.getElementById('outMonthlyPv').innerText = Math.round(monthlyPv).toLocaleString() + ' PV';
      document.getElementById('outDailyRevenue').innerText = '$' + dailyUsd.toFixed(2) + ' (약 ' + Math.round(dailyKrw).toLocaleString() + '원)';
      document.getElementById('outMonthlyRevenue').innerText = '$' + monthlyUsd.toFixed(2) + ' (약 ' + Math.round(monthlyKrw).toLocaleString() + '원)';
      document.getElementById('outFlippaVal').innerText = '$' + Math.round(flippaUsd).toLocaleString() + ' (약 ' + Math.round(flippaKrw / 10000).toLocaleString() + '만 원)';
    }
    calculate();
